/// `RouteOut` is the callback type for routing `IOI` messages.
pub type RouteOut = fn(msg: IOI, session_id: SessionID) -> Result<(), MessageRejectErrorEnum>;

/// Route type returned by the `route` function.
pub type Route = (&'static str, &'static str, Box<dyn Fn(&Message, SessionID) -> Result<(), MessageRejectErrorEnum> + Send>);

/// Returns the begin string, message type, and route function for `IOI`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(IOI::from_message(msg.clone()), session_id)
    };
    ("FIX.4.3", "6", Box::new(r))
}
